script:
frappe.ui.form.on('Payment Entry', {
    refresh(frm) {
        // add a hook so whenever the references table changes, we populate Fees Type
        frm.fields_dict.references.grid.wrapper.on('change', async function () {
            await populate_fees_type(frm);
        });
    },

    // also run after fetching outstanding invoices (button populates rows)
    get_outstanding_invoices(frm) {
        setTimeout(() => populate_fees_type(frm), 800);
    }
});

async function populate_fees_type(frm) {
    let rows = frm.doc.references || [];

    for (let row of rows) {
        if (row.reference_doctype === "Sales Invoice" && row.reference_name) {

            let r = await frappe.db.get_value(
                "Sales Invoice",
                row.reference_name,
                "custom_fees_type"
            );

            frappe.model.set_value(
                row.doctype,
                row.name,
                "custom_fees_type",
                r.message.custom_fees_type || null
            );
        }
    }
}

frappe.ui.form.on("Student", {
  guardian_is(frm) {
    if (frm.doc.guardian_is === "Father") {
      frm.set_value("guardian_name", frm.doc.father_name);
      frm.set_value("guardian_phone", frm.doc.father_phone);
      frm.set_value("guardian_occupation", frm.doc.father_occupation);
      frm.set_value("guardian_relation", "Father");
    }

    if (frm.doc.guardian_is === "Mother") {
      frm.set_value("guardian_name", frm.doc.mother_name);
      frm.set_value("guardian_phone", frm.doc.mother_phone);
      frm.set_value("guardian_occupation", frm.doc.mother_occupation);
      frm.set_value("guardian_relation", "Mother");
    }
  }
});
